import "@/utils/disposablePolyfill.ts";
import type { Grid } from "healpix-geo";

import type { ProjectionHelper } from "@/lib/projection/projectionUtils.ts";
import { buildHistogramSummary } from "@/utils/histogram.ts";

export const HEALPIX_NUMCHUNKS = 12;

/**
 * Names to try for the cell-id coordinate: the one named by the dggs
 * convention, otherwise "cell" and then "cell_ids" (the xdggs default).
 */
export function healpixCellCoordinateNames(coordinate?: string | null) {
  return coordinate ? [coordinate] : ["cell", "cell_ids"];
}

function distanceSquared(
  x1: number,
  y1: number,
  z1: number,
  x2: number,
  y2: number,
  z2: number
): number {
  return (x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1) + (z2 - z1) * (z2 - z1);
}

function generateHealpixIndices(positionValues: Float32Array, steps: number) {
  const indices = [];
  for (let i = 0; i < steps - 1; ++i) {
    for (let j = 0; j < steps - 1; ++j) {
      const a = i * steps + (j + 1);
      const b = i * steps + j;
      const c = (i + 1) * steps + j;
      const d = (i + 1) * steps + (j + 1);
      const dac2 = distanceSquared(
        positionValues[3 * a + 0],
        positionValues[3 * a + 1],
        positionValues[3 * a + 2],
        positionValues[3 * c + 0],
        positionValues[3 * c + 1],
        positionValues[3 * c + 2]
      );
      const dbd2 = distanceSquared(
        positionValues[3 * b + 0],
        positionValues[3 * b + 1],
        positionValues[3 * b + 2],
        positionValues[3 * d + 0],
        positionValues[3 * d + 1],
        positionValues[3 * d + 2]
      );
      if (dac2 < dbd2) {
        indices.push(a, c, d);
        indices.push(b, c, a);
      } else {
        indices.push(a, b, d);
        indices.push(b, c, d);
      }
    }
  }
  return indices;
}

const FULL_FACE: THealpixDataRect = { u: 0, v: 0, width: 1, height: 1 };

/**
 * The texture is interpolated linearly between vertices, but the face-to-
 * lat/lon mapping is curved: over a whole face (~110 km quads) that misplaces
 * data by up to ~1 km. Meshing only the data rect shrinks that quadratically.
 */
export function buildHealpixGeometry(
  grid: Grid,
  ipix: bigint,
  steps: number,
  helper: ProjectionHelper,
  dataRect: THealpixDataRect = FULL_FACE
) {
  const rect = dataRect.width > 0 ? dataRect : FULL_FACE;
  const vertexCount = steps * steps;
  const positionValues = new Float32Array(vertexCount * 3);
  const uv = new Float32Array(vertexCount * 2);
  const latLonValues = new Float32Array(vertexCount * 2);
  let vertexIndex = 0;

  for (let i = 0; i < steps; ++i) {
    for (let j = 0; j < steps; ++j) {
      // UVs stay face-global; the shader maps them into the data rect.
      const u = rect.u + (rect.width * i) / (steps - 1);
      const v = rect.v + (rect.height * j) / (steps - 1);
      using coordinate = grid.vertex(ipix, u, v);

      const positionOffset = vertexIndex * 3;
      helper.projectLatLonToArrays(
        coordinate.lat,
        coordinate.lon,
        positionValues,
        positionOffset,
        latLonValues,
        vertexIndex * 2
      );

      const uvIndex = vertexIndex * 2;
      uv[uvIndex] = u;
      uv[uvIndex + 1] = v;

      vertexIndex++;
    }
  }

  const indices = generateHealpixIndices(positionValues, steps);
  return {
    positionValues,
    uv,
    latLonValues,
    indices: new Uint32Array(indices),
  };
}

// A face-local rectangle, normalized to [0, 1] across the whole face, that the
// texture covers. Lets the shader map a full-face UV onto a texture that only
// covers the (small) region a regional/sparse dataset, or the finite values of
// a dense one, actually has data for.
export type THealpixDataRect = {
  u: number;
  v: number;
  width: number;
  height: number;
};

export function buildHealpixRegionCoordinates(
  grid: Grid,
  faceIndex: number,
  rect: THealpixDataRect
) {
  using faceGrid = grid.replace({ level: 0, scheme: "nested" });
  // Sample the curved rectangle at 16 subdivisions per axis;
  // increase this if tighter framing than the camera's 5% margin is needed.
  const subdivisions = 16;
  const coordinates = new Float32Array((subdivisions + 1) ** 2 * 2);
  let offset = 0;
  for (let i = 0; i <= subdivisions; i++) {
    for (let j = 0; j <= subdivisions; j++) {
      using point = faceGrid.vertex(
        BigInt(faceIndex),
        rect.u + (rect.width * i) / subdivisions,
        rect.v + (rect.height * j) / subdivisions
      );
      coordinates[offset++] = point.lat;
      coordinates[offset++] = point.lon;
    }
  }
  return coordinates;
}

export function decodeHealpixFaceXY(pixel: number) {
  let x = 0;
  let y = 0;
  for (let bit = 1; pixel > 0; bit *= 2) {
    x += (pixel % 2) * bit;
    y += (Math.floor(pixel / 2) % 2) * bit;
    pixel = Math.floor(pixel / 4);
  }
  return { x, y };
}

export function getHealpixTextureIndex(pixel: number, nside: number) {
  const { x, y } = decodeHealpixFaceXY(pixel);
  return y * nside + x;
}

type TFaceBBox = { minX: number; minY: number; maxX: number; maxY: number };

// First x in [from, to] (walking by `step`) of row y holding a finite value, or -1.
function findFiniteX(
  data: Float32Array,
  spread: Uint32Array,
  y: number,
  from: number,
  to: number,
  step: 1 | -1
) {
  const rowBits = spread[y] * 2;
  for (let x = from; x !== to + step; x += step) {
    if (Number.isFinite(data[spread[x] + rowBits])) {
      return x;
    }
  }
  return -1;
}

// Face-local bounding box of the finite values of a dense face. Scans inwards
// from the edges, so a face with values along its border costs O(nside).
function getDenseFiniteBBox(
  data: Float32Array,
  spread: Uint32Array,
  nside: number
): TFaceBBox | null {
  const last = nside - 1;
  let minY = 0;
  while (minY < nside && findFiniteX(data, spread, minY, 0, last, 1) < 0) {
    minY++;
  }
  if (minY === nside) {
    return null;
  }
  let maxY = last;
  while (findFiniteX(data, spread, maxY, 0, last, 1) < 0) {
    maxY--;
  }
  let minX = last;
  let maxX = 0;
  for (let y = minY; y <= maxY && (minX > 0 || maxX < last); y++) {
    const left = minX > 0 ? findFiniteX(data, spread, y, 0, minX - 1, 1) : -1;
    const right =
      maxX < last ? findFiniteX(data, spread, y, last, maxX + 1, -1) : -1;
    minX = left >= 0 ? left : minX;
    maxX = right >= 0 ? right : maxX;
  }
  return { minX, minY, maxX, maxY };
}

function buildDenseHealpixTexture(
  data: Float32Array,
  nside: number,
  cropToData: boolean
) {
  // Interleave each axis separately: O(nside) lookup storage instead of O(nside²).
  const spread = new Uint32Array(nside);
  for (let index = 1; index < nside; index++) {
    spread[index] = spread[index >> 1] * 4 + (index & 1);
  }
  const fullFace = { minX: 0, minY: 0, maxX: nside - 1, maxY: nside - 1 };
  const bbox =
    (cropToData && getDenseFiniteBBox(data, spread, nside)) || fullFace;
  const width = bbox.maxX - bbox.minX + 1;
  const height = bbox.maxY - bbox.minY + 1;
  const dataValues = new Float32Array(width * height);
  let min = Number.POSITIVE_INFINITY;
  let max = Number.NEGATIVE_INFINITY;
  let index = 0;
  for (let y = bbox.minY; y <= bbox.maxY; y++) {
    const rowBits = spread[y] * 2;
    for (let x = bbox.minX; x <= bbox.maxX; x++) {
      const value = data[spread[x] + rowBits];
      dataValues[index++] = value;
      if (Number.isFinite(value)) {
        min = Math.min(min, value);
        max = Math.max(max, value);
      }
    }
  }
  if (min === Number.POSITIVE_INFINITY) {
    min = max = NaN;
  }
  return {
    dataValues,
    width,
    height,
    dataRect: {
      u: bbox.minX / nside,
      v: bbox.minY / nside,
      width: width / nside,
      height: height / nside,
    } as THealpixDataRect,
    histogramSummary: buildHistogramSummary(dataValues, min, max),
  };
}

function getFaceCellBBox(cells: number[], faceOffset: number, faceEnd: number) {
  let minX = Number.POSITIVE_INFINITY;
  let minY = Number.POSITIVE_INFINITY;
  let maxX = -1;
  let maxY = -1;
  for (const cell of cells) {
    if (cell < faceOffset || cell >= faceEnd) {
      continue;
    }
    const { x, y } = decodeHealpixFaceXY(cell - faceOffset);
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
    minY = Math.min(minY, y);
    maxY = Math.max(maxY, y);
  }
  return maxX < minX ? null : { minX, minY, maxX, maxY };
}

export function getHealpixFaceDataRect(
  faceIndex: number,
  nside: number,
  cells: number[]
): THealpixDataRect | null {
  const faceOffset = faceIndex * nside * nside;
  const bbox = getFaceCellBBox(cells, faceOffset, faceOffset + nside * nside);
  return bbox
    ? {
        u: bbox.minX / nside,
        v: bbox.minY / nside,
        width: (bbox.maxX - bbox.minX + 1) / nside,
        height: (bbox.maxY - bbox.minY + 1) / nside,
      }
    : null;
}

function fillFaceBBoxTexture(
  data: Float32Array,
  cells: number[],
  faceOffset: number,
  faceEnd: number,
  bbox: { minX: number; minY: number },
  width: number,
  height: number
) {
  const { minX, minY } = bbox;
  const dataValues = new Float32Array(width * height).fill(NaN);
  let min = Number.POSITIVE_INFINITY;
  let max = Number.NEGATIVE_INFINITY;
  for (let index = 0; index < cells.length; index++) {
    const cell = cells[index];
    if (cell < faceOffset || cell >= faceEnd) {
      continue;
    }
    const { x, y } = decodeHealpixFaceXY(cell - faceOffset);
    const value = data[index];
    dataValues[(y - minY) * width + (x - minX)] = value;
    if (Number.isFinite(value)) {
      min = Math.min(min, value);
      max = Math.max(max, value);
    }
  }
  if (min === Number.POSITIVE_INFINITY) {
    min = max = NaN;
  }
  return {
    dataValues,
    histogramSummary: buildHistogramSummary(dataValues, min, max),
  };
}

// A regional/sparse dataset (a "cell" coordinate naming the actual pixels)
// typically covers only a tiny fraction of a face, especially at deep levels
// where nside² is far too large to allocate for the whole face. Size the
// texture to the bounding box of the cells actually present instead.
function buildSparseHealpixTexture(
  data: Float32Array,
  batchIndex: number,
  nside: number,
  cells: number[]
) {
  const faceOffset = batchIndex * nside * nside;
  const faceEnd = faceOffset + nside * nside;
  const dataRect = getHealpixFaceDataRect(batchIndex, nside, cells);
  if (!dataRect) {
    // None of the cells fall in this face.
    return {
      dataValues: new Float32Array(0),
      width: 0,
      height: 0,
      dataRect: { u: 0, v: 0, width: 0, height: 0 } as THealpixDataRect,
      histogramSummary: buildHistogramSummary(new Float32Array(0), NaN, NaN),
    };
  }
  const bbox = { minX: dataRect.u * nside, minY: dataRect.v * nside };
  const width = dataRect.width * nside;
  const height = dataRect.height * nside;
  const { dataValues, histogramSummary } = fillFaceBBoxTexture(
    data,
    cells,
    faceOffset,
    faceEnd,
    bbox,
    width,
    height
  );
  return {
    dataValues,
    width,
    height,
    dataRect,
    histogramSummary,
  };
}

/**
 * With `cropDenseToData`, a dense face is cropped to the bounding box of its
 * finite values, like a sparse face to its cells. Only use it when the mesh is
 * built from the returned dataRect: a texture swapped onto an existing mesh
 * must keep the whole face.
 */
export function buildHealpixTexture(
  data: Float32Array,
  batchIndex: number,
  nside: number,
  cells?: number[],
  { cropDenseToData = false } = {}
) {
  return cells
    ? buildSparseHealpixTexture(data, batchIndex, nside, cells)
    : buildDenseHealpixTexture(data, nside, cropDenseToData);
}

export function getHealpixFaceRange(
  faceIndex: number,
  nside: number,
  cells?: number[]
) {
  const pixelStart = faceIndex * nside * nside;
  const pixelEnd = pixelStart + nside * nside;
  if (!cells) {
    return { start: pixelStart, end: pixelEnd, cells };
  }
  // 12 scans avoid a full-grid map; index ranges if sparse scans become expensive.
  let start = cells.length;
  let end = 0;
  for (let index = 0; index < cells.length; index++) {
    if (cells[index] >= pixelStart && cells[index] < pixelEnd) {
      start = Math.min(start, index);
      end = index + 1;
    }
  }
  return { start: Math.min(start, end), end, cells: cells.slice(start, end) };
}
